#!/usr/local/bin/node
'use strict';

const cluster=String(process.argv[2]||'A').toUpperCase();
const agentsOnly=process.argv.includes('--agents-only');
const sx=Number(process.argv[3]||0), sy=Number(process.argv[4]||0), sw=Number(process.argv[5]||1792), sh=Number(process.argv[6]||1120);

function def(c){
  if(c==='A') return {start:1,end:8,controllerPort:19311};
  if(c==='B') return {start:9,end:16,controllerPort:19312};
  if(c==='C') return {start:17,end:27,controllerPort:19313};
  if(c==='D') return {start:28,end:38,controllerPort:19314};
  throw new Error('cluster invalid');
}
const d=def(cluster);

const TOP=24, GAPX=3, GAPY=4, CTRL_GAP=4;
const CTRL_H=Math.max(92,Math.min(100,Math.floor(sh*0.086)));
const AGENT_H=sh-TOP-CTRL_H-CTRL_GAP;
const IS_C=(cluster==='C'||cluster==='D');
const GRID_COLS=3, GRID_ROWS=4;
const C_RIGHT_GAP=IS_C?10:0;
const C_VERT_GAP=IS_C?6:0;
const C_VERT_TARGET=IS_C?500:0;
const C_LEFT_W=IS_C?sw-C_RIGHT_GAP-C_VERT_GAP-C_VERT_TARGET:sw;

const ROW_H=IS_C
  ? Math.floor((AGENT_H-(GRID_ROWS-1)*GAPY)/GRID_ROWS)
  : Math.floor((AGENT_H-GAPY)/2);

const CELL_W=IS_C
  ? Math.floor((C_LEFT_W-(GRID_COLS-1)*GAPX)/GRID_COLS)
  : Math.floor((sw-3*GAPX)/4);
const BOTTOM_W=4*CELL_W+3*GAPX;
const BOTTOM_X=IS_C?sx:sx+Math.floor((sw-BOTTOM_W)/2);
const C_VERT_X=IS_C?sx+sw-C_RIGHT_GAP-C_VERT_TARGET:sx+sw;
const C_VERT_W=IS_C?C_VERT_TARGET:0;
const CTRL_TOP=sy+sh-CTRL_H;

const sleep=ms=>new Promise(r=>setTimeout(r,ms));

async function json(url,opts={}){
  const r=await fetch(url,{...opts,signal:AbortSignal.timeout(3000)});
  if(!r.ok)throw new Error('HTTP '+r.status);
  return await r.json();
}

async function rpc(wsUrl,method,params={}){
  const ws=new WebSocket(wsUrl);
  await new Promise((resolve,reject)=>{
    const t=setTimeout(()=>reject(new Error('ws open timeout')),5000);
    ws.onopen=()=>{clearTimeout(t);resolve();};
    ws.onerror=()=>{clearTimeout(t);reject(new Error('ws error'));};
  });
  const id=1;
  const out=await new Promise((resolve,reject)=>{
    const t=setTimeout(()=>reject(new Error(method+' timeout')),7000);
    ws.onmessage=e=>{
      let m;try{m=JSON.parse(e.data)}catch{return}
      if(m.id!==id)return;
      clearTimeout(t);
      if(m.error)reject(new Error(m.error.message||'cdp error'));
      else resolve(m.result||{});
    };
    ws.send(JSON.stringify({id,method,params}));
  });
  try{ws.close()}catch{}
  return out;
}

async function ensureChatPage(agent){
  const port=19400+agent;
  let list=await json('http://127.0.0.1:'+port+'/json/list');
  let p=list.find(t=>t.type==='page');

  if(!p){
    const ver=await json('http://127.0.0.1:'+port+'/json/version');

    await rpc(
      ver.webSocketDebuggerUrl,
      'Target.createTarget',
      {
        url:'https://chatgpt.com/',
        newWindow:true
      }
    );

    for(let i=0;i<20;i++){
      await sleep(200);
      list=await json('http://127.0.0.1:'+port+'/json/list');
      p=list.find(t=>t.type==='page');
      if(p)break;
    }
  }

  if(!p)throw new Error('page-create-failed');
  for(const x of list.filter(t=>t.type==='page'&&t.id!==p.id)){
    try{
      await fetch(
        'http://127.0.0.1:'+port+'/json/close/'+x.id,
        {signal:AbortSignal.timeout(2000)}
      );
    }catch{}
  }
  if(!(p.url||'').startsWith('https://chatgpt.com/')){
    await rpc(p.webSocketDebuggerUrl,'Page.navigate',{url:'https://chatgpt.com/'});
    await sleep(1000);
    const x=await json('http://127.0.0.1:'+port+'/json/list');
    p=x.find(t=>t.type==='page'&&t.id===p.id) || x.find(t=>t.type==='page');
  }
  if(!p)throw new Error('page missing after navigate');
  return {port,page:p};
}

async function setBounds(port,page,bounds){
  const ver=await json('http://127.0.0.1:'+port+'/json/version');
  const w=await rpc(ver.webSocketDebuggerUrl,'Browser.getWindowForTarget',{targetId:page.id});
  await rpc(ver.webSocketDebuggerUrl,'Browser.setWindowBounds',{
    windowId:w.windowId,
    bounds:{...bounds,windowState:'normal'}
  });
  return w.windowId;
}

async function tileAgent(agent,index){
  const {port,page}=await ensureChatPage(agent);
  let bounds;
  if(IS_C && agent===d.end){
    bounds={left:C_VERT_X,top:sy+TOP,width:C_VERT_W,height:AGENT_H};
  }else if(IS_C){
    const col=index%GRID_COLS;
    const row=Math.floor(index/GRID_COLS);
    bounds={
      left:sx+col*(CELL_W+GAPX),
      top:sy+TOP+row*(ROW_H+GAPY),
      width:CELL_W,
      height:ROW_H
    };
  }else if(index<4){
    bounds={left:sx+index*(CELL_W+GAPX),top:sy+TOP,width:CELL_W,height:ROW_H};
  }else{
    const col=index-4;
    bounds={left:BOTTOM_X+col*(CELL_W+GAPX),top:sy+TOP+ROW_H+GAPY,width:CELL_W,height:ROW_H};
  }
  await setBounds(port,page,bounds);
  return {agent,...bounds};
}

async function tileController(){
  const port=d.controllerPort;
  const list=await json('http://127.0.0.1:'+port+'/json/list');
  const p=list.find(t=>t.type==='page');
  if(!p)throw new Error('controller page missing');
  const bounds={left:sx,top:CTRL_TOP,width:sw,height:CTRL_H};
  await setBounds(port,p,bounds);
  return bounds;
}

(async()=>{
  // Snap controller first so drag-release feels immediate.
  const controller=agentsOnly?null:await tileController();
  const jobs=[];
  let idx=0;
  for(let a=d.start;a<=d.end;a++,idx++){
    const agent=a, index=idx;
    jobs.push((async()=>{
      let last='';
      for(let k=0;k<2;k++){
        try{
          const r=await tileAgent(agent,index);
          console.error('TILE_OK',agent);
          return r;
        }catch(e){
          last=e.message;
          console.error('TILE_RETRY',agent,k+1,last);
          await sleep(250);
        }
      }
      return {agent,error:last||'tile failed'};
    })());
  }
  const agents=await Promise.all(jobs);
  console.log(JSON.stringify({
    cluster,screen:{sx,sy,sw,sh},
    metrics:{cellWidth:CELL_W,rowHeight:ROW_H,controllerHeight:CTRL_H},
    agents,controller
  }));
})().catch(e=>{console.error(e.stack||e);process.exit(1)});
